  const S1P_FULLSCREEN_MODAL_CLASS = "s1p-fullscreen-modal";
  const S1P_LAYERED_MODAL_BACKDROP_OPEN_CLASS =
    "s1p-layered-modal-backdrop-open";
  const S1P_LAYERED_MODAL_CONTENT_OPEN_CLASS =
    "s1p-layered-modal-content-open";
