  const S1P_LAYERED_MODAL_CLOSING_CLASS = "s1p-modal-closing";
  const S1P_LAYERED_MODAL_BACKDROP_ANIMATION_MS = 160;
  const S1P_LAYERED_MODAL_CONTENT_ENTER_DELAY_MS = 170;
  const S1P_LAYERED_MODAL_ANIMATION_FALLBACK_GAP_MS = 60;
  const S1P_SETTINGS_SECONDARY_GLASS_CLASS = "s1p-settings-secondary-glass";
  const S1P_SETTINGS_SECONDARY_MODAL_CLASS = "s1p-settings-secondary-modal";
  const S1P_SETTINGS_SECONDARY_MODAL_DETACHED_CLASS =
    "s1p-settings-secondary-modal--detached";
  const S1P_SETTINGS_SECONDARY_MODAL_BACKDROP_ANIMATION_MS = 200;
  const S1P_DIALOG_CONTENT_CLASS = "s1p-dialog-content";
  const S1P_DIALOG_CONTENT_SIZE_CLASS_NAMES = Object.freeze({
    compact: "s1p-dialog-content--compact",
    default: "s1p-dialog-content--default",
    wide: "s1p-dialog-content--wide",
    expanded: "s1p-dialog-content--expanded",
  });
  const S1P_FIRST_LEVEL_GLASS_CLASS = "s1p-first-level-glass";
  const S1P_FIRST_LEVEL_GLASS_SETTINGS_PRESET_CLASS =
    "s1p-first-level-glass--settings";
  const S1P_FIRST_LEVEL_GLASS_CONFIRM_PRESET_CLASS =
    "s1p-first-level-glass--confirm";
  const buildS1pFullscreenModalClassName = (...classNames) =>
    [S1P_FULLSCREEN_MODAL_CLASS, ...classNames]
      .filter(Boolean)
      .join(" ");
  const buildSettingsSecondaryGlassClassName = (...classNames) =>
    [S1P_SETTINGS_SECONDARY_GLASS_CLASS, ...classNames]
      .filter(Boolean)
      .join(" ");
  const buildSettingsSecondaryModalClassName = (...classNames) =>
    [S1P_SETTINGS_SECONDARY_MODAL_CLASS, ...classNames]
      .filter(Boolean)
      .join(" ");
  const buildFirstLevelGlassClassName = (presetClassName, ...classNames) =>
    [...classNames, S1P_FIRST_LEVEL_GLASS_CLASS, presetClassName]
      .filter(Boolean)
      .join(" ");
  const buildS1pDialogContentClassName = (
    surfaceContext,
    size = "default",
    ...classNames
  ) => {
    const sizeClassName =
      S1P_DIALOG_CONTENT_SIZE_CLASS_NAMES[size] ||
      S1P_DIALOG_CONTENT_SIZE_CLASS_NAMES.default;
    const structuralClassNames = [
      S1P_DIALOG_CONTENT_CLASS,
      sizeClassName,
      ...classNames,
    ];
    return surfaceContext?.isSettingsSecondaryModal
      ? buildSettingsSecondaryGlassClassName(...structuralClassNames)
      : buildFirstLevelGlassClassName(
        S1P_FIRST_LEVEL_GLASS_CONFIRM_PRESET_CLASS,
        ...structuralClassNames
      );
  };
  const isSettingsSecondaryGlassContext = (anchor = null) =>
    Boolean(
      anchor?.closest?.(
        `.s1p-modal, .${S1P_SETTINGS_SECONDARY_MODAL_CLASS}:not(.${S1P_SETTINGS_SECONDARY_MODAL_DETACHED_CLASS})`
      )
    );

  const S1P_BASE_CSS_RESOURCE_NAME = "s1p-base-css";
  const S1P_BASE_CSS_TOKEN_VALUES = Object.freeze({
    "__S1P_NARROW_SCREEN_MAX_WIDTH_PX_PLUS_1__": NARROW_SCREEN_MAX_WIDTH_PX + 1,
    "__S1P_NARROW_SCREEN_MAX_WIDTH_PX__": NARROW_SCREEN_MAX_WIDTH_PX,
    "__S1P_AUTO_SYNC_INDICATOR_ENTER_DURATION_MS__": AUTO_SYNC_INDICATOR_ENTER_DURATION_MS,
    "__S1P_AUTO_SYNC_INDICATOR_EXIT_DURATION_MS__": AUTO_SYNC_INDICATOR_EXIT_DURATION_MS,
    "__S1P_LAYERED_MODAL_BACKDROP_ANIMATION_MS__": S1P_LAYERED_MODAL_BACKDROP_ANIMATION_MS,
    "__S1P_LAYERED_MODAL_BACKDROP_OPEN_CLASS__": S1P_LAYERED_MODAL_BACKDROP_OPEN_CLASS,
    "__S1P_LAYERED_MODAL_CONTENT_OPEN_CLASS__": S1P_LAYERED_MODAL_CONTENT_OPEN_CLASS,
    "__S1P_LAYERED_MODAL_CONTENT_ENTER_DELAY_MS__": S1P_LAYERED_MODAL_CONTENT_ENTER_DELAY_MS,
    "__S1P_SETTINGS_SECONDARY_MODAL_BACKDROP_ANIMATION_MS__": S1P_SETTINGS_SECONDARY_MODAL_BACKDROP_ANIMATION_MS,
    "__S1P_SVG_ICON_ARROW_MASK__": SVG_ICON_ARROW_MASK,
    "__S1P_SVG_ICON_DELETE_DEFAULT__": SVG_ICON_DELETE_DEFAULT,
    "__S1P_SVG_ICON_DELETE_HOVER__": SVG_ICON_DELETE_HOVER,
    "__S1P_IMAGE_VIEWER_OPEN_CLOSE_ANIMATION_MS__": S1P_IMAGE_VIEWER_OPEN_CLOSE_ANIMATION_MS,
    "__S1P_IMAGE_VIEWER_SWITCH_ANIMATION_MS__": S1P_IMAGE_VIEWER_SWITCH_ANIMATION_MS,
    "__S1P_IMAGE_VIEWER_SWITCH_OFFSET_PX__": S1P_IMAGE_VIEWER_SWITCH_OFFSET_PX,
  });
  const loadS1pBaseCss = () => {
    if (typeof GM_getResourceText !== "function") {
      return "";
    }
    let cssText = "";
    try {
      cssText = GM_getResourceText(S1P_BASE_CSS_RESOURCE_NAME);
    } catch (error) {
      return "";
    }
    if (typeof cssText !== "string" || !cssText) {
      return "";
    }
    return Object.entries(S1P_BASE_CSS_TOKEN_VALUES).reduce(
      (resolvedCss, [token, value]) =>
        resolvedCss.split(token).join(String(value)),
      cssText
    );
  };
  const s1pBaseCssText = loadS1pBaseCss();
  if (s1pBaseCssText) {
    GM_addStyle(s1pBaseCssText);
  }

  // --- S1 NUX 兼容性检测 ---
  let isS1NuxEnabled = false;
  const NUX_DARK_TEXT_MIN_CONTRAST_RATIO = 2.8;
  const NUX_DARK_TEXT_FIX_CLASS = "s1p-nux-dark-text-fixed";
  const NUX_LIGHT_BG_CONTENT_CLASS = "s1p-light-bg-content";
  const NUX_LIGHT_BG_MIN_LUMINANCE = 0.72;
